  "expression": "div(gain, cost) + min(rarity, 1.0)",
  "rationale": "Combining the base greedy ratio gain/cost with rarity prioritizes vertices that cover hard-to-cover elements, helping the constructor avoid getting stuck with expensive leftover vertices while keeping the core efficiency metric intact."
}

{
  "expression": "div(gain, cost) + 0.35 * rarity * (1.0 - overlap)",
  "rationale": "Combines efficiency (gain/cost) with coverage quality. Rarity prioritizes vertices that cover hard-to-cover elements, while low overlap minimizes redundancy with already covered vertices."
}

{
  "expression": "div(gain, add(cost, multiply(0.1, overlap)))",
  "rationale": "Incorporates overlap into the denominator to penalize vertices that cover excessive already-covered neighbors, prioritizing vertices with cleaner coverage while retaining the core efficiency ratio div(gain, cost)."
}

{
  "expression": "div(gain, cost) + div(rarity, cost) - max(overlap, 0.1)",
  "rationale": "Extends the baseline gain-to-cost ratio by prioritizing vertices covering rare (hard-to-cover) vertices via the rarity feature, while slightly penalizing high neighborhood overlap to reduce structural redundancy prior to the pruning step."
}

{
  "expression": "div(gain, cost) + rarity - 0.1 * overlap",
  "rationale": "Extends the best parent gain/cost + rarity by introducing a small penalty for overlap, discouraging candidate vertices that re-cover already dominated neighbors."
}

{
  "expression": "div(gain, cost) + div(rarity, cost) - div(overlap, cost)",
  "rationale": "Extends the greedy baseline by combining normalized gain and rarity (favoring vertices covering hard-to-cover elements) while penalizing neighborhood overlap with already covered regions, all relative to vertex cost."
}

{
  "expression": "div(gain, cost) + 0.35 * gain * rarity * (1.0 - overlap)",
  "rationale": "Enhances the greedy baseline by adding a secondary priority term that favors vertices covering rare (hard-to-cover) vertices with low neighborhood overlap, promoting efficient coverage before pruning."
}

{
  "expression": "div(gain, cost) + div(rarity, cost) - div(overlap, cost)",
